// Synthetic fixtures only; no patient metadata. Generated by Scripts/generate_strict_codec_fixtures.py.
// JPEG: Pillow/libjpeg; JPEG-LS: pyjpegls/CharLS; SOF3 constants independently verified by pylibjpeg-libjpeg.
import Foundation
import Testing
@testable import DICOMCore

@Suite("Independent compressed frame samples")
struct IndependentCompressedFrameTests {
    @Test func independentSamplesAndColor() throws {
        let fixtures: [(name: String, uid: String, bits: Int, spp: Int, rows: Int, cols: Int,
                        pi: PhotometricInterpretation, encoded: String, expected: String, tolerance: Int)] = [
            ("CharLS monochrome 8", TransferSyntax.jpegLSLossless.uid, 8, 1, 8, 16, .monochrome2,
             "/9j/9wALCAAIABABAREA/9oACAEBAAAAAJGTaVV4AAAK8AAACvsm0qrsff99AAAAV/9/4+//eXPhlfi18XP+LX//AP/Z",
             "AP369/Tx7uvo5eLf3NnW09DNysfEwb67uLWyr6yppqOgnZqXlJGOi4iFgn98eXZzcG1qZ2RhXltYVVJPTElGQ0A9Ojc0MS4rKCUiHxwZFhMQDQoHBAH++/j18u/s6ebj4N3a19TRzsvIxcK/vLm2s7CtqqekoZ6bmJWSj4yJhoM=", 0),
            ("CharLS monochrome 12", TransferSyntax.jpegLSLossless.uid, 12, 1, 8, 16, .monochrome2,
             "/9j/9wALDAAIABABAREA/9oACAEBAAAAAIAAeQAB5fu/V+b8X3vtfW+l875Xxvhe+vgAD1AgghCEBfhEREBgXYiIkgW5JJAwLMkkkCvJKgXlWqqCnVUFxRqqgn1VBaTaqoJdeCwk/wI/4P/Z",
             "", 0),
            ("CharLS monochrome 16", TransferSyntax.jpegLSLossless.uid, 16, 1, 8, 16, .monochrome2,
             "",
             "", 0),
            ("T81 constant verified by libjpeg 8", TransferSyntax.jpegLosslessSV1.uid, 8, 1, 2, 3, .monochrome2,
             "/9j/wwALCAACAAMBAREA/8QAFAABAAAAAAAAAAAAAAAAAAAAAP/aAAgBAQABAAAD/9k=",
             "gICAgICA", 0),
            ("T81 constant verified by libjpeg 12", TransferSyntax.jpegLosslessSV1.uid, 12, 1, 2, 3, .monochrome2,
             "/9j/wwALDAACAAMBAREA/8QAFAABAAAAAAAAAAAAAAAAAAAAAP/aAAgBAQABAAAD/9k=",
             "AAgACAAIAAgACAAI", 0),
            ("T81 constant verified by libjpeg 16", TransferSyntax.jpegLosslessSV1.uid, 16, 1, 2, 3, .monochrome2,
             "/9j/wwALEAACAAMBAREA/8QAFAABAAAAAAAAAAAAAAAAAAAAAP/aAAgBAQABAAAD/9k=",
             "AIAAgACAAIAAgACA", 0),
            ("libjpeg YBR", TransferSyntax.jpegBaseline.uid, 8, 3, 8, 16, .ybrFull,
             "",
             "", 3),
            ("libjpeg RGB", TransferSyntax.jpegBaseline.uid, 8, 3, 8, 16, .rgb,
             "",
             "", 3),
            ("CharLS RGB source planar 0", TransferSyntax.jpegLSLossless.uid, 8, 3, 8, 16, .rgb,
             "/9j/9wARCAAIABADAREAAhEAAxEA/9oADAMBAAIAAwAAAgAAEAATvyVb/3gAAAmYAAANmBsRYixFiLEWIsRZL7Agg/UEEHiEIdIQhwhCGERGERH/2Q==",
             "", 0),
            ("CharLS RGB source planar 1", TransferSyntax.jpegLSLossless.uid, 8, 3, 8, 16, .rgb,
             "/9j/9wARCAAIABADAREAAhEAAxEA/9oACAEBAAAAAAA8rwAAATOV8+z9Xi6eHDhg/9oACAECAAAAAAAAAdGV4AAANnGMYzMz7P1eLp4cOGD/2gAIAQMAAAAAANK8AAAEylfPs/V4unhw4YD/2Q==",
             "", 0)
        ]
        for f in fixtures {
            let descriptor = PixelDataDescriptor(rows: f.rows, columns: f.cols,
                bitsAllocated: f.bits > 8 ? 16 : 8, bitsStored: f.bits, highBit: f.bits - 1,
                isSigned: false, samplesPerPixel: f.spp, photometricInterpretation: f.pi)
            let codec = try #require(CodecRegistry.shared.codec(for: f.uid))
            let encoded = try #require(Data(base64Encoded: f.encoded))
            let expected = try #require(Data(base64Encoded: f.expected))
            let decoded = try codec.decodePixelFrame(encoded, descriptor: descriptor, frameIndex: 0)
            #expect(decoded.data.count == expected.count, "\(f.name)")
            #expect(zip(decoded.data, expected).allSatisfy { abs(Int($0) - Int($1)) <= f.tolerance }, "\(f.name)")
            #expect(decoded.sourceFrameIndex == 0)
            #expect(decoded.descriptor.photometricInterpretation == (f.spp == 3 ? .rgb : .monochrome2))
            if f.spp == 3 {
                let planar = PixelDataDescriptor(rows: f.rows, columns: f.cols,
                    bitsAllocated: 8, bitsStored: 8, highBit: 7, isSigned: false, samplesPerPixel: 3,
                    photometricInterpretation: f.pi, planarConfiguration: 1)
                let result = try codec.decodePixelFrame(encoded, descriptor: planar, frameIndex: 0)
                let expectedPlanar = Data((0..<3).flatMap { c in (0..<(f.rows * f.cols)).map { expected[$0 * 3 + c] } })
                #expect(zip(result.data, expectedPlanar).allSatisfy { abs(Int($0) - Int($1)) <= f.tolerance }, "\(f.name) planar")
            }
        }
    }
}
